import Foundation
#if canImport(CryptoKit)
import CryptoKit
#else
import Crypto
#endif

/// `.cas.torrent`：在标准 BitTorrent 元数据里塞一段 `x-cas` 扩展，
/// 记录 file_md5 / slice_md5 / 每片 md5，从而**只凭种子就能秒传**（不需要本地文件）。
///
/// 结构（与天翼云盘 App 的 CasParser 一致）：
/// ```
/// d
///   comment:        "Generated by <app> with CAS extension"
///   created by:     <app>
///   creation date:  <unix ts>
///   info:  d
///     length:       <file size>
///     md5sum:       <FILE_MD5>          # 大写
///     name:         <file name>
///     piece length: 10485760
///     pieces:       <每片 SHA1 的原始字节拼接>
///   e
///   x-cas: d
///     cloud:      "189"
///     file_md5:   <FILE_MD5>
///     slice_md5:  <SLICE_MD5>
///     slice_md5s: l <每片 MD5> … e
///     slice_size: 10485760
///   e
/// e
/// ```
public enum CasTorrent {

    public struct ParseError: Error, LocalizedError {
        public let message: String
        public var errorDescription: String? { message }
    }

    // MARK: - 生成

    /// 从本地文件生成 `.cas.torrent`
    public static func build(fromFile url: URL,
                             createdBy: String = "cas189-ios",
                             creationDate: Date = Date()) throws -> Data {
        let attrs = try FileManager.default.attributesOfItem(atPath: url.path)
        let size = (attrs[.size] as? NSNumber)?.int64Value ?? 0
        let sliceSize = C.sliceSize
        let handle = try FileHandle(forReadingFrom: url)
        defer { try? handle.close() }

        var whole = Insecure.MD5()
        var md5Parts: [String] = []
        var sha1Concat = Data()

        while true {
            let chunk = handle.readData(ofLength: sliceSize)
            if chunk.isEmpty { break }
            whole.update(data: chunk)
            md5Parts.append(md5Hex(chunk))
            sha1Concat.append(Data(Insecure.SHA1.hash(data: chunk)))
        }
        // 空文件也要给一个分片占位，和 App 行为一致
        if md5Parts.isEmpty {
            md5Parts = [md5Hex(Data())]
            sha1Concat = Data(Insecure.SHA1.hash(data: Data()))
        }

        let fileMd5 = whole.finalize().map { String(format: "%02X", $0) }.joined()
        let sliceMd5 = CryptoTool.sliceMd5OfParts(md5Parts)

        let info = Bencode.Value.dict([
            ("length", .int(Int(size))),
            ("md5sum", .str(fileMd5)),
            ("name", .str(url.lastPathComponent)),
            ("piece length", .int(sliceSize)),
            ("pieces", .bytes(sha1Concat))
        ])
        let xcas = Bencode.Value.dict([
            ("cloud", .str("189")),
            ("file_md5", .str(fileMd5)),
            ("slice_md5", .str(sliceMd5)),
            ("slice_md5s", .list(md5Parts.map { Bencode.str($0) })),
            ("slice_size", .int(sliceSize))
        ])
        let root = Bencode.Value.dict([
            ("comment", .str("Generated by \(createdBy) with CAS extension")),
            ("created by", .str(createdBy)),
            ("creation date", .int(Int(creationDate.timeIntervalSince1970))),
            ("info", info),
            ("x-cas", xcas)
        ])
        return Bencode.encode(root)
    }

    // MARK: - 解析

    /// 解析 `.cas.torrent`，得到可以直接喂给 `rapidUpload(_:)` 的 CasItem
    public static func parse(_ data: Data) throws -> CasItem {
        let root = try Bencode.decode(data)
        guard let info = root.get("info"), info.dictValue != nil else {
            throw ParseError(message: "torrent 缺少 info")
        }

        // 名字（优先 utf-8 变体）
        let rawName = info.get("name.utf-8")?.stringValue
            ?? info.get("name")?.stringValue
            ?? "unknown"

        // 单文件取 length；多文件取 files 里第一个
        var size: Int64 = (info.get("length")?.intValue).map(Int64.init) ?? 0
        if size == 0, let files = info.get("files")?.listValue, let first = files.first {
            size = (first.get("length")?.intValue).map(Int64.init) ?? 0
            if let pathParts = first.get("path.utf-8")?.listValue ?? first.get("path")?.listValue,
               !pathParts.isEmpty {
                // 多文件场景用第一个文件名，避免和父目录混淆
                let joined = pathParts.compactMap { $0.stringValue }.joined(separator: "/")
                if !joined.isEmpty { return try buildItem(name: joined, size: size, info: info, root: root) }
            }
        }
        return try buildItem(name: rawName, size: size, info: info, root: root)
    }

    private static func buildItem(name: String, size: Int64,
                                  info: Bencode.Value, root: Bencode.Value) throws -> CasItem {
        var fileMd5 = info.get("md5sum")?.stringValue?.uppercased() ?? ""
        var sliceMd5 = ""
        var sliceSize = (info.get("piece length")?.intValue) ?? C.sliceSize
        var parts: [String] = []

        if let xcas = root.get("x-cas"), xcas.dictValue != nil {
            if let v = xcas.get("file_md5")?.stringValue, !v.isEmpty { fileMd5 = v.uppercased() }
            if let v = xcas.get("slice_md5")?.stringValue, !v.isEmpty { sliceMd5 = v.uppercased() }
            if let v = xcas.get("slice_size")?.intValue, v > 0 { sliceSize = v }
            if let list = xcas.get("slice_md5s")?.listValue {
                parts = list.compactMap { $0.stringValue?.uppercased() }
            }
        }

        guard !fileMd5.isEmpty else {
            throw ParseError(message: "torrent 的 x-cas 缺少 file_md5")
        }
        if sliceMd5.isEmpty { sliceMd5 = fileMd5 }
        if parts.isEmpty && size > Int64(sliceSize) {
            throw ParseError(message: "该 .cas.torrent 缺少 x-cas 分片信息（大于 10MB 的文件必须用它才能秒传）")
        }
        return CasItem(name: name, size: size, fileMd5: fileMd5,
                       sliceMd5: sliceMd5, sliceSize: sliceSize, parts: parts)
    }

    // MARK: - 辅助

    private static func md5Hex(_ data: Data) -> String {
        Insecure.MD5.hash(data: data).map { String(format: "%02X", $0) }.joined()
    }
}
